$pdo=db();if(session_status()!==PHP_SESSION_ACTIVE)session_start();$fails=[];$ok=static function(bool $v,string $m)use(&$fails){echo($v?'PASS ':'FAIL ').$m.PHP_EOL;if(!$v)$fails[]=$m;};$suffix=bin2hex(random_bytes(4));$password='SecurePass'.$suffix.'9A';
