$token=bin2hex(random_bytes(32));$pdo->prepare("INSERT INTO classroom_members(classroom_id,user_id,session_token,membership_status,last_seen_at) VALUES(?,?,?,'active',NOW())")->execute([$classId,$sid,$token]);$member=(int)$pdo->lastInsertId();$duplicate=false;try{$pdo->prepare("INSERT INTO classroom_members(classroom_id,user_id,session_token,membership_status) VALUES(?,?,?,'active')")->execute([$classId,$sid,bin2hex(random_bytes(32))]);}catch(PDOException){$duplicate=true;}$ok($duplicate,'Student cannot join same Classroom twice');
$old=$class['code'];$new='ENG-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));$pdo->prepare('UPDATE classrooms SET code=? WHERE id=?')->execute([$new,$classId]);$pdo->prepare('INSERT INTO classroom_code_history(classroom_id,old_code,new_code,changed_by) VALUES(?,?,?,?)')->execute([$classId,$old,$new,$tid]);$ok(!(new ClassroomService($pdo))->findActiveByCode($old)&&(new ClassroomService($pdo))->findActiveByCode($new)!==false,'Classroom ID regeneration invalidates old code');
$pdo->prepare('UPDATE classrooms SET join_open=0 WHERE id=?')->execute([$classId]);$ok(!(new ClassroomService($pdo))->findActiveByCode($new),'closed Classroom rejects new joins');
