$chars='📖 🎧 🎤 ✍️ 🏆 🎮 ·';$ok(mb_check_encoding($chars,'UTF-8')&&mb_strlen($chars)>7,'required emoji and separator are valid UTF-8');
$pdo->prepare('DELETE FROM classrooms WHERE id=?')->execute([$classId]);$pdo->prepare('DELETE FROM users WHERE id IN (?,?)')->execute([$tid,$sid]);$pdo->prepare('DELETE FROM login_attempts WHERE identity_hash IN (?,?)')->execute([hash('sha256',"teacher-{$suffix}@example.test"),hash('sha256',"student-{$suffix}@example.test")]);
